const image=(label,c)=>`data:image/svg+xml;base64,${Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1280 960"><rect width="1280" height="960" fill="${c}"/><circle cx="1010" cy="160" r="95" fill="#f4d99a"/><path d="M0 710L200 420l200 175 220-270 210 225 180-150 300 300v260H0z" fill="#647857"/><text x="55" y="875" fill="white" font-size="54" font-family="Arial">${label}</text></svg>`).toString('base64')}`;

function makeState(count=12,extra=true){
 const missionEvidence={},missionStatus={},visited=[];
 ids.slice(0,count).forEach((id,i)=>{const d=i<5?11:i<10?12:13,h=i<5?9+i:i<10?9+i-5:10+i-10,t=iso(d,h);missionEvidence[id]={id,verified:true,photo:image(id,colors[i]),title:`Recuerdo ${id}`,place:`Lugar ${id}`,comment:`Comentario del recuerdo ${id}${i===3?'. Texto largo para comprobar composición, legibilidad y saltos de línea. '.repeat(4):'.'}`,by:i%2?'Laura':'Ismael',distance:20+i,completedAt:t,updatedAt:t};missionStatus[id]={done:true,completedAt:t,updatedAt:t};visited.push(id)});
 if(extra){const t=iso(12,8,50);missionEvidence.auschwitz={id:'auschwitz',extra:true,bonus:true,verified:true,photo:image('Auschwitz-Birkenau','#888780'),title:'Visita a Auschwitz-Birkenau',place:'Auschwitz-Birkenau',comment:'Una visita para recordar y aprender, con respeto y sin gamificación.',by:'Ambos',distance:64,completedAt:t,updatedAt:t}}
 return{visited,missionEvidence,missionStatus,memories:[{id:'m1',title:'La primera tarde',note:'Un recuerdo escrito largo. '.repeat(18),place:'Planty',by:'Laura',ts:iso(11,18),updatedAt:iso(11,18)},{id:'m2',title:'Algo que nos hizo gracia',note:'Un pequeño momento que queríamos conservar.',place:'Stare Miasto',by:'Ismael',ts:iso(12,18),updatedAt:iso(12,18)}],expenses:[{id:'e1',amount:24.6,category:'food',ts:iso(11,14),updatedAt:iso(11,14)}],config:{dailyTarget:21,fixedPaid:0},updatedAt:iso(13,19)};
}
const full=makeState();
const report={target:base,version:'5.0',generatedAt:new Date().toISOString(),engines:[],failures:[]};

function cloud(initial){
 let server=clone(initial);return{get:()=>clone(server),set:s=>server=clone(s),route:async r=>{const u=r.request().url();if(u.includes('adventure_get'))return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(server)});if(u.includes('adventure_put')){try{const b=JSON.parse(r.request().postData()||'{}');if(b?.p_state)server=clone(b.p_state)}catch{};return r.fulfill({status:200,contentType:'application/json',body:'{}'})}return r.fulfill({status:200,contentType:'application/json',body:'{}'})}};
}
async function contextFor(browser,state,shared,player='Ismael',printSpy=false){
 const ctx=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:2,acceptDownloads:true,serviceWorkers:'block'});
 await ctx.addInitScript(({state,player,printSpy})=>{localStorage.setItem('krakowPocketCoop',JSON.stringify(state));localStorage.setItem('krakowPlayer',player);if(printSpy){window.__auditPrintCalled=false;window.print=()=>{window.__auditPrintCalled=true}}},{state:clone(state),player,printSpy});
 await ctx.route('https://ahzmwkztlakejmrvgcdm.supabase.co/rest/v1/rpc/**',shared.route);
 const page=await ctx.newPage();await page.goto(base,{waitUntil:'domcontentloaded',timeout:30000});await page.waitForFunction(()=>window.KP_ALBUM_V5?.version==='5.0'&&window.KP_MISSION_PROOF?.version==='2.0'&&window.KP_AUSCHWITZ_EXTRA?.version==='2.0'&&window.KP_STATE_BRIDGE?.bridgeRevision==='20260812c'&&window.KP_STABILITY?.albumIframeGuardRevision==='20260812b',{timeout:20000});return{ctx,page};
}

for(const [engineName,engine] of engines){
 const checks=[],errors=[];const check=(n,ok,d='')=>{checks.push({name:n,ok:!!ok,detail:d});if(!ok)report.failures.push(`${engineName}: ${n}${d?` — ${d}`:''}`)};let browser;
 try{
  browser=await engine.launch({headless:true});
  // Isolated edge cases.
  for(const edge of [{name:'empty',state:{visited:[],missionEvidence:{},missionStatus:{},memories:[],expenses:[],config:{dailyTarget:21,fixedPaid:0},updatedAt:iso(11,8)},photos:0},{name:'one-photo',state:makeState(1,false),photos:1}]){const sh=cloud(edge.state),e=await contextFor(browser,edge.state,sh);const h=await e.page.evaluate(()=>window.KP_ALBUM_V5.html());check(`${edge.name} photo count`,(h.match(/class="photo-card/g)||[]).length===edge.photos);check(`${edge.name} Story availability`,edge.photos?h.includes('id="storyAlbum"'):!h.includes('id="storyAlbum"'));if(!edge.photos)check('empty album message',h.includes('Todavía no hay fotografías guardadas'));await e.ctx.close()}

  const shared=cloud(full),A=await contextFor(browser,full,shared,'Ismael',true),page=A.page;page.on('pageerror',e=>errors.push(`pageerror:${e}`));page.on('console',m=>{if(m.type()==='error'&&!/favicon|Failed to load resource/.test(m.text()))errors.push(`console:${m.text()}`)});await page.waitForTimeout(900);await page.evaluate(()=>document.querySelector('.tab[data-panel="diary"]')?.click());await page.waitForTimeout(250);
  const arch=await page.evaluate(()=>({v5:window.KP_ALBUM_V5?.singleSource,experience:window.KP_ALBUM_EXPERIENCE?.unifiedSingleSource,proof:window.KP_MISSION_PROOF?.legacyAlbumUi===false&&window.KP_MISSION_PROOF?.legacyAlbumExporter===false,aus:window.KP_AUSCHWITZ_EXTRA?.legacyAlbumExporter===false,atomic:window.KP_STATE_BRIDGE?.atomicSharedFieldAdoption===true,diary:window.KP_STATE_BRIDGE?.staleDiaryRecordProtection===true,scroll:window.KP_STABILITY?.albumIframePagehideCapture===true,legacyGlobals:!!(window.KP_ALBUM_V3_POLISH||window.KP_ALBUM_DIGITAL_V4||window.KP_ALBUM_DIGITAL_RUNTIME_FIX||window.KP_ALBUM_DIGITAL_AMBIENT_FIX),legacyDom:document.querySelectorAll('#kpAlbumCard,#kpAlbumDialog,#kpAlbumExperienceCard,#kpAlbumExperienceDialog').length,legacyScripts:[...document.scripts].filter(s=>/album-(experience|v3|digital-v4|ios-compat)/.test(s.src)).length}));check('single-source architecture',arch.v5&&arch.experience&&arch.proof&&arch.aus&&arch.atomic&&arch.diary&&arch.scroll&&!arch.legacyGlobals&&arch.legacyDom===0&&arch.legacyScripts===0,JSON.stringify(arch));await page.evaluate(()=>{window.dispatchEvent(new Event('pageshow'));window.dispatchEvent(new CustomEvent('kp:mission-evidence-sync',{detail:{}}));document.dispatchEvent(new Event('visibilitychange'))});await page.waitForTimeout(450);check('legacy album cannot reappear',(await page.locator('#kpAlbumCard,#kpAlbumDialog,#kpAlbumExperienceCard,#kpAlbumExperienceDialog').count())===0);

  const html=await page.evaluate(()=>window.KP_ALBUM_V5.html()),refs=(html.match(/data:image\//g)||[]).length;check('standalone has 13 photos',(html.match(/class="photo-card/g)||[]).length===13);check('Auschwitz is memory extra',html.includes('EXTRA · MEMORIA')&&html.includes('sin gamificación'));check('long content survives',html.includes('Texto largo para comprobar composición')&&html.includes('Un recuerdo escrito largo'));check('standalone is self-contained',!/<script[^>]+src=/i.test(html)&&!/<link[^>]+stylesheet/i.test(html)&&!/(cdn\.jsdelivr|unpkg|googleapis)/i.test(html));check('image embedding bounded',refs<=14,`${refs}`);check('print/reduced-motion styles',html.includes('@media print')&&html.includes('prefers-reduced-motion:reduce'));

  const printOk=await page.evaluate(()=>window.KP_ALBUM_V5.print());await page.waitForSelector('#kpAlbumV5Dialog[open]');const f=page.frameLocator('#kpAlbumV5Frame');await f.locator('[data-kp-album-v5="1"]').waitFor();check('PDF waits for loaded iframe',printOk&&await f.locator('body').evaluate(()=>window.__auditPrintCalled===true));await page.locator('#kpAlbumV5Close').click();await page.waitForFunction(()=>!document.documentElement.classList.contains('kp-album-v5-open'));
  for(let i=0;i<(engineName==='webkit'?5:2);i++){await page.locator('#kpAlbumV5Open').click();await f.locator('[data-kp-album-v5="1"]').waitFor();await page.locator('#kpAlbumV5Close').click();await page.waitForFunction(()=>!document.querySelector('#kpAlbumV5Dialog')?.open)}check('repeated open/close',true);await page.locator('#kpAlbumV5Open').click();await f.locator('.photo-card').first().waitFor();check('viewer 13 photos',(await f.locator('.photo-card').count())===13);check('viewer multiple chapters',(await f.locator('.chapter').count())>=3);check('viewer memories',(await f.locator('.memory-card').count())===2);

  const matrix=[];for(const width of [320,390,430,768]){await page.setViewportSize({width,height:844});await page.waitForTimeout(90);matrix.push({width,...await f.locator('html').evaluate(()=>({cw:document.documentElement.clientWidth,sw:document.documentElement.scrollWidth,toolbar:document.querySelector('.toolbar').scrollWidth-document.querySelector('.toolbar').clientWidth,minTap:Math.min(...[...document.querySelectorAll('.toolbar a,.toolbar button,.story-controls button,.overlay-close')].filter(x=>x.getBoundingClientRect().height>0).map(x=>x.getBoundingClientRect().height))}))})}check('responsive no overflow',matrix.every(x=>x.sw<=x.cw+1),JSON.stringify(matrix));check('toolbar no clipping',matrix.every(x=>x.toolbar<=1));check('touch targets >=40px',matrix.every(x=>x.minTap>=40));await page.setViewportSize({width:390,height:844});

  await f.locator('.photo-button').first().click();const lb=f.locator('#lightbox');check('lightbox opens',await lb.evaluate(e=>e.classList.contains('open')));const l1=await f.locator('#lightbox img').getAttribute('src');await f.locator('.lightbox-next').click();const l2=await f.locator('#lightbox img').getAttribute('src');check('lightbox next',l1!==l2);await f.locator('.lightbox-prev').click();check('lightbox previous',(await f.locator('#lightbox img').getAttribute('src'))===l1);await page.keyboard.press('Escape');check('Escape closes lightbox',!(await lb.evaluate(e=>e.classList.contains('open'))));
  await f.locator('#storyAlbum').click();const story=f.locator('#storyMode');check('Story opens',await story.evaluate(e=>e.classList.contains('open')));check('filmstrip has 13 thumbs',(await f.locator('.filmstrip button').count())===13);const s1=(await f.locator('.story-position').textContent()).trim();await f.locator('#storyNext').click();const s2=(await f.locator('.story-position').textContent()).trim();check('Story next',s1!==s2,`${s1}->${s2}`);await f.locator('.filmstrip button').nth(4).click();check('filmstrip jump',(await f.locator('.story-position').textContent()).includes('5 / 13'));await f.locator('.story-play').click();const a1=(await f.locator('.story-position').textContent()).trim();await page.waitForTimeout(4700);const a2=(await f.locator('.story-position').textContent()).trim();check('autoplay advances',a1!==a2,`${a1}->${a2}`);await f.locator('.story-play').click();const paused=(await f.locator('.story-position').textContent()).trim();await page.waitForTimeout(4700);check('pause stops autoplay',(await f.locator('.story-position').textContent()).trim()===paused);

  await page.evaluate(()=>{memoryTitle.value='Recuerdo en vivo';memoryNote.value='Añadido con Historia abierta';memoryPlace.value='Cracovia';memoryForm.requestSubmit()});await page.waitForFunction(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').memories?.some(x=>x.title==='Recuerdo en vivo'));await page.waitForTimeout(1400);check('live save keeps Story open',await story.evaluate(e=>e.classList.contains('open')));await f.locator('#storyMode .overlay-close').click();let live=false;try{await f.locator('text=Recuerdo en vivo').waitFor({state:'visible',timeout:4500});live=true}catch{}check('deferred refresh after Story',live);
  await f.locator('html').evaluate(()=>{document.documentElement.style.scrollBehavior='auto';scrollTo(0,180)});await page.waitForTimeout(100);const y1=await f.locator('body').evaluate(()=>scrollY);await page.evaluate(()=>{memoryTitle.value='Scroll estable';memoryNote.value='Recuerdo nuevo';memoryPlace.value='Cracovia';memoryForm.requestSubmit()});await page.waitForTimeout(1900);const y2=await f.locator('body').evaluate(()=>scrollY);check('non-zero scroll stable',Math.abs(y2-y1)<=4,`${y1}->${y2}`);await f.locator('html').evaluate(()=>{document.documentElement.style.scrollBehavior='auto';scrollTo(0,0)});await page.waitForTimeout(100);await page.evaluate(()=>{memoryTitle.value='Scroll cero';memoryNote.value='Recuerdo arriba';memoryPlace.value='Cracovia';memoryForm.requestSubmit()});await page.waitForTimeout(1900);const y0=await f.locator('body').evaluate(()=>scrollY);check('zero scroll stable',Math.abs(y0)<=4,`0->${y0}`);

  // Let local writes settle, then create a genuine second iPhone from the shared cloud.
  await page.waitForTimeout(1800);const B=await contextFor(browser,shared.get(),shared,'Laura',false);await B.page.waitForTimeout(1200);const remoteTs='2026-08-14T00:01:00+02:00';await B.page.evaluate(({remoteTs})=>{const k='krakowPocketCoop',s=JSON.parse(localStorage.getItem(k)||'{}');s.missionEvidence.bernatek={...s.missionEvidence.bernatek,title:'Recuerdo remoto de Laura',comment:'Cambio nuevo enviado desde el segundo iPhone',by:'Laura',updatedAt:remoteTs};s.updatedAt=remoteTs;localStorage.setItem(k,JSON.stringify(s));window.dispatchEvent(new CustomEvent('kp:mission-evidence-local',{detail:{id:'bernatek',entry:s.missionEvidence.bernatek}}));const target=document.getElementById('dailyTarget');if(target){target.value=String(Number(target.value||21)+1);target.dispatchEvent(new Event('change',{bubbles:true}))}},{remoteTs});await B.page.waitForFunction(()=>window.KP_STATE_BRIDGE?.protectedMissionEvidence?.().bernatek?.title==='Recuerdo remoto de Laura');
  await B.page.waitForTimeout(1800);let cloudRemote=false;for(let i=0;i<16;i++){if(shared.get().missionEvidence?.bernatek?.title==='Recuerdo remoto de Laura'){cloudRemote=true;break}await B.page.waitForTimeout(500)}check('second iPhone pushes newer evidence',cloudRemote,String(shared.get().missionEvidence?.bernatek?.title));
  let bothConverged=false;for(let i=0;i<32;i++){const av=await page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title),bv=await B.page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title),sv=shared.get().missionEvidence?.bernatek?.title;if(av==='Recuerdo remoto de Laura'&&bv==='Recuerdo remoto de Laura'&&sv==='Recuerdo remoto de Laura'){bothConverged=true;break}await page.waitForTimeout(500)}check('two iPhones converge on newer evidence',bothConverged,`A=${await page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title)} B=${await B.page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title)} cloud=${shared.get().missionEvidence?.bernatek?.title}`);await page.waitForTimeout(6500);const finalA=await page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title),finalB=await B.page.evaluate(()=>JSON.parse(localStorage.getItem('krakowPocketCoop')||'{}').missionEvidence?.bernatek?.title),finalCloud=shared.get().missionEvidence?.bernatek?.title;check('newer evidence survives later cycles',finalA==='Recuerdo remoto de Laura'&&finalB==='Recuerdo remoto de Laura'&&finalCloud==='Recuerdo remoto de Laura',`A=${finalA} B=${finalB} cloud=${finalCloud}`);const canonical=await page.evaluate(()=>window.KP_ALBUM_V5.html());check('album generator contains remote evidence',canonical.includes('Recuerdo remoto de Laura'));let shown=false;try{await f.locator('text=Recuerdo remoto de Laura').waitFor({state:'visible',timeout:5000});shown=true}catch{}check('open album refreshes to remote evidence',shown);await B.ctx.close();

  let downloaded='';try{const [dl]=await Promise.all([page.waitForEvent('download',{timeout:5000}),page.evaluate(()=>window.KP_ALBUM_V5.download())]);const path=await dl.path();if(path)downloaded=fs.readFileSync(path,'utf8')}catch(e){errors.push(`download:${e}`)}check('download is current V5',downloaded.includes('data-kp-album-v5="1"')&&downloaded.includes('Recuerdo remoto de Laura')&&downloaded.includes('Auschwitz-Birkenau'),`${downloaded.length}`);const dupes=await f.locator('html').evaluate(()=>{const m=new Map(),o=[];document.querySelectorAll('[id]').forEach(e=>m.set(e.id,(m.get(e.id)||0)+1));m.forEach((n,id)=>{if(n>1)o.push([id,n])});return o});check('no duplicate IDs',dupes.length===0,JSON.stringify(dupes));await page.locator('#kpAlbumV5Close').click();await page.waitForFunction(()=>!document.documentElement.classList.contains('kp-album-v5-open'));
  const noJs=await browser.newContext({viewport:{width:390,height:844},javaScriptEnabled:false});const np=await noJs.newPage();await np.setContent(downloaded||html,{waitUntil:'domcontentloaded'});const info=await np.evaluate(()=>({overflow:document.documentElement.scrollWidth-document.documentElement.clientWidth,story:document.querySelector('#storyAlbum')?getComputedStyle(document.querySelector('#storyAlbum')).display:'absent',photos:document.querySelectorAll('.photo-card').length,top:document.querySelector('a[href="#albumTop"]')?.getAttribute('href'),index:document.querySelector('a[href="#albumIndex"]')?.getAttribute('href'),pdf:document.querySelector('#albumPrint')?.getAttribute('href'),end:document.querySelector('a[href="#albumEnd"]')?.getAttribute('href')}));check('Quick Look/no-JS works',info.overflow<=1&&(info.story==='none'||info.story==='absent')&&info.photos===13&&info.top==='#albumTop'&&info.index==='#albumIndex'&&info.pdf==='#pdfHelp'&&info.end==='#albumEnd',JSON.stringify(info));await noJs.close();check('no runtime JS errors',errors.length===0,errors.join(' | ').slice(0,1400));await A.ctx.close();
 }catch(e){check('audit has no unhandled exception',false,String(e?.stack||e).slice(0,1800))}finally{try{await browser?.close()}catch{};report.engines.push({engine:engineName,checks,errors})}
}
fs.writeFileSync('/tmp/album-v5-final-audit-r4.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(report.failures.length)process.exitCode=1;
